output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "Customers are obliged to check out the provided cart from the entrance cart station before completing the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)",
        "cart_available_here": "cartAt(1,5)",
        "cart_in_possession": "hasCart"
      },
      "events": {
        "pickup_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "cart_available_here",
              "PICKUP_CART"
            ]
          },
          "post": "cart_in_possession"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entrance_cart"
    }
  },
  {
    "id": "no_item_without_cart",
    "text": "Customers are prohibited from taking shelf items unless they currently have the shopping cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_possession": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "shelf_item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelf_item_pickup",
          "without_cart"
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Customers are prohibited from carrying groceries by hand rather than placing them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "cart_in_possession": "hasCart"
      },
      "events": {
        "item_pickup_to_hand": {
          "pre": "PICKUP_ITEM",
          "post": "carrying_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "item_pickup_to_hand"
        ]
      }
    }
  },
  {
    "id": "return_cart_after_use",
    "text": "After taking a cart, customers are obliged to return it to the customer-service return point before the trajectory ends.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)",
        "return_station": "at(0,1)",
        "cart_in_possession": "hasCart",
        "cart_parked_at_return": "cartAt(0,1)"
      },
      "events": {
        "cart_checked_out": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "cart_in_possession"
        },
        "proper_cart_return": {
          "pre": {
            "and": [
              "return_station",
              "cart_in_possession",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_checked_out",
      "discharge": "proper_cart_return"
    }
  },
  {
    "id": "leave_cart_only_at_return",
    "text": "Customers are prohibited from putting the cart down anywhere except the designated return station at customer service.",
    "abstraction": {
      "state_properties": {
        "return_station": "at(0,1)",
        "not_at_return_station": {
          "not": "at(0,1)"
        },
        "cart_in_possession": "hasCart"
      },
      "events": {
        "cart_drop": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_drop",
          "not_at_return_station"
        ]
      }
    }
  },
  {
    "id": "no_exit_before_cart_return",
    "text": "Customers are prohibited from exiting unless the cart has already been parked at the return station and they are no longer pushing it.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_return": "cartAt(0,1)",
        "cart_in_possession": "hasCart",
        "properly_on_foot_after_return": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "exit_store": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          {
            "not": "properly_on_foot_after_return"
          }
        ]
      }
    }
  },
  {
    "id": "no_shopping_after_return",
    "text": "Once the cart is parked at the return station, customers are prohibited from doing any further store interaction.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_return": "cartAt(0,1)",
        "post_return_mode": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "any_store_interaction": {
          "pre": "INTERACT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "post_return_mode",
          "any_store_interaction"
        ]
      }
    }
  },
  {
    "id": "no_cart_in_exit_corridor",
    "text": "Carts are prohibited in the exit-side corridor, so customers must leave the cart behind before approaching the exit area.",
    "abstraction": {
      "state_properties": {
        "exit_side_corridor": {
          "or": [
            "at(9,1)",
            "at(9,2)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        },
        "cart_in_possession": "hasCart",
        "pushing_cart_in_exit_corridor": {
          "and": [
            "hasCart",
            "exit_side_corridor"
          ]
        }
      },
      "events": {
        "enter_exit_side_corridor_with_cart": {
          "pre": "pushing_cart_in_exit_corridor",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushing_cart_in_exit_corridor"
    }
  }
]
